values (md5('PE-013:policy:booking_rule:2')::uuid, 'PE-013', 'https://kidsplaytown.ca/visit.html', '2026-11-07', 'verified', null, 'booking_rule', 'On peak days (Saturdays, Sundays and PA Days) capacity is sometimes limited. On weekends, or if you''re travelling far, check Playtown''s Facebook page or call first.', 2);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-013:policy:other:3')::uuid, 'PE-013', 'https://kidsplaytown.ca/visit.html', '2026-11-07', 'verified', null, 'other', 'Payment is by e-transfer (preferred) or cash.', 3);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-013:policy:dress_socks:4')::uuid, 'PE-013', 'https://kidsplaytown.ca/parties.html', '2026-11-07', 'verified', null, 'dress_socks', 'Socks only: all kids and adults must wear socks. Socks are sold at reception for kids and adults.', 4);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-013:policy:supervision:5')::uuid, 'PE-013', 'https://kidsplaytown.ca/about.html', '2026-11-07', 'verified', null, 'supervision', 'No child can enter or exit without a parent, and no adult can enter without a child. Exit doors are alarmed, and parents are encouraged to play along in the playhouses.', 5);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-013:policy:food_rule:6')::uuid, 'PE-013', 'https://kidsplaytown.ca/faqs.html', '2026-11-07', 'verified', null, 'food_rule', 'Food from home is allowed for daily play and parties, but it can''t contain peanuts or nuts.', 6);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-013:policy:restriction:7')::uuid, 'PE-013', 'https://kidsplaytown.ca/faqs.html', '2026-11-07', 'verified', null, 'restriction', 'Children in potty training must wear diapers for the whole visit.', 7);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-013:policy:restriction:8')::uuid, 'PE-013', 'https://kidsplaytown.ca/faqs.html', '2026-11-07', 'verified', null, 'restriction', 'No alcohol at any time, including private parties.', 8);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-013:policy:restriction:9')::uuid, 'PE-013', 'https://kidsplaytown.ca/parties.html', '2026-11-07', 'verified', null, 'restriction', 'Children who are unwell during their visit will be asked to leave. No rough play.', 9);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-013:policy:party:10')::uuid, 'PE-013', 'https://kidsplaytown.ca/parties.html', '2026-11-07', 'verified', 'An older copy of the Parties page at www.kidsplaytown.ca lists a $545 private party (6–9 pm, facility only, no food) and packages for up to 12 or 24 children.', 'party', 'Each party has a 2-hour slot plus 15 minutes for setup, and access to all of the play section. Packages count kids and adults together. The Enchanted Castle isn''t available for double-room parties. The cafeteria is included only with a private party. Bring your own cutlery, plates, cups and napkins. No food or drinks in the play area ($200 fine). On arrival you sign a form and give contact details.', 10);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-013:policy:party:11')::uuid, 'PE-013', 'https://kidsplaytown.ca/faqs.html', '2026-11-07', 'verified', null, 'party', 'The play area stays open for daily play during parties and is shared with party guests. Confirm your guest count at least 3 days ahead.', 11);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-013:policy:cancellation:12')::uuid, 'PE-013', 'https://kidsplaytown.ca/parties.html', '2026-11-07', 'verified', 'The older www.kidsplaytown.ca copy of the Parties page gives a deposit-based policy: more than 14 days, deposit transferable; 7–14 days, 50%; under 7 days, forfeited.', 'cancellation', 'Party cancellations within 48 hours of the party pay the full balance.', 12);

